<?php require 'config.php'; fechar_offlines(); $alertas=gerar_alertas_inteligentes(); header_page('Diagnóstico');
$scan=jread('scan_status',[]); $disp=jread('dispositivos',[]); $funs=jread('funcionarios',[]); $logs=array_reverse(jread('logs',[])); $conf=jread('config',[]);
$ultimo=$scan['ultimo_scan']??''; $seg=$ultimo?time()-strtotime($ultimo):999999; $leitorOk=$ultimo && $seg<180; $semVinculo=0; foreach($disp as $d){ if(empty($d['funcionario_id'])) $semVinculo++; }
?>
<section class="hero"><div><h2>Diagnóstico inteligente</h2><p>Verifica leitor, site, rede, vínculos e possíveis falhas de ponto.</p></div><span class="pill <?=$leitorOk?'ok':'off'?>"><?=$leitorOk?'Sistema operacional':'Atenção necessária'?></span></section>
<section class="grid"><div class="card"><p>Site PHP</p><div class="big ok">OK</div><p><?=now()?> · <?=date_default_timezone_get()?></p></div><div class="card"><p>Leitor Windows</p><div class="big <?=$leitorOk?'ok':'off'?>"><?=$leitorOk?'ATIVO':'PARADO'?></div><p>Último scan: <?=h($ultimo ?: '--')?><?= $ultimo?' · há '.$seg.'s':'' ?></p></div><div class="card"><p>Aparelhos detectados</p><div class="big"><?=count($disp)?></div><p>Sem vínculo: <?=$semVinculo?></p></div><div class="card"><p>Alertas</p><div class="big <?=count($alertas)?'warn':'ok'?>"><?=count($alertas)?></div><p>Inteligência <?=!empty($conf['inteligencia_ativa'])?'ativa':'desativada'?></p></div></section><br>
<?php if($alertas): ?><div class="card"><h2>O que precisa de atenção</h2><div class="alerts"><?php foreach($alertas as $a): ?><div class="alert <?=h($a['nivel'])?>"><b><?=h($a['titulo'])?></b><span><?=h($a['texto'])?></span></div><?php endforeach; ?></div></div><br><?php endif; ?>
<div class="card"><h2>Checklist rápido</h2><table><tr><th>Item</th><th>Status</th><th>Observação</th></tr><tr><td>Horário Brasília</td><td><span class="pill ok">OK</span></td><td><?=now()?></td></tr><tr><td>IP do PC configurado</td><td><span class="pill <?=!empty($conf['ip_pc'])?'ok':'off'?>"><?=!empty($conf['ip_pc'])?'OK':'Falta'?></span></td><td><?=h($conf['ip_pc']??'')?></td></tr><tr><td>Leitor enviando dados</td><td><span class="pill <?=$leitorOk?'ok':'off'?>"><?=$leitorOk?'OK':'Verificar'?></span></td><td>Se estiver parado, abra o leitor Python.</td></tr><tr><td>Funcionários cadastrados</td><td><span class="pill <?=count($funs)>0?'ok':'off'?>"><?=count($funs)>0?'OK':'Falta'?></span></td><td><?=count($funs)?> funcionário(s)</td></tr><tr><td>Aparelhos sem vínculo</td><td><span class="pill <?=$semVinculo==0?'ok':'warn'?>"><?=$semVinculo==0?'OK':'Verificar'?></span></td><td><?=$semVinculo?> aparelho(s)</td></tr></table></div><br>
<div class="card"><h2>Aparelhos</h2><table><tr><th>IP</th><th>MAC</th><th>Funcionário</th><th>Último visto</th><th>Online?</th></tr><?php foreach($disp as $d): $nome='Sem vínculo'; foreach($funs as $f){ if($f['id']===($d['funcionario_id']??'')) $nome=$f['nome']; } $on=!empty($d['ultimo_visto']) && time()-strtotime($d['ultimo_visto']) <= ((int)($conf['tolerancia_offline_min']??15))*60; ?><tr><td><?=h($d['ip']??'')?></td><td><?=h($d['mac']??'')?></td><td><?=h($nome)?></td><td><?=h($d['ultimo_visto']??'')?></td><td><span class="pill <?=$on?'ok':'off'?>"><?=$on?'Sim':'Não'?></span></td></tr><?php endforeach; ?></table></div><br>
<div class="card"><h2>Últimos logs</h2><table><tr><th>Data</th><th>Tipo</th><th>Mensagem</th></tr><?php foreach(array_slice($logs,0,50) as $l): ?><tr><td><?=h($l['data']??'')?></td><td><?=h($l['tipo']??'')?></td><td><?=h($l['mensagem']??'')?></td></tr><?php endforeach; ?></table></div>
<?php footer_page(); ?>
